package de.corporate.lc.user.service;
import de.corporate.lc.user.domain.AppUser;import de.corporate.lc.user.repository.AppUserRepository;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.util.Optional;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class TotpServiceTest {
 @Test void enablesTotpAndConsumesRecoveryCodeOnlyOnce(){AppUser user=new AppUser();user.setUsername("editor");user.setPasswordHash(new BCryptPasswordEncoder().encode("ValidPassword1"));AppUserRepository repo=mock(AppUserRepository.class);when(repo.findByUsernameIgnoreCase("editor")).thenReturn(Optional.of(user));TotpService service=new TotpService(repo,new BCryptPasswordEncoder(),"0123456789abcdef0123456789abcdef");TotpService.Setup setup=service.setup("editor");var recovery=service.enable("editor",setup.secret(),service.currentCode(setup.secret()));assertThat(user.isTotpEnabled()).isTrue();assertThat(setup.qrCodeDataUrl()).startsWith("data:image/png;base64,");assertThat(recovery).hasSize(8);assertThat(service.verifyLogin("editor",recovery.get(0))).isTrue();assertThat(service.verifyLogin("editor",recovery.get(0))).isFalse();}
}
